-- =====================================================================
-- Helper Academy — v24: "Feelings: Word Scales" — feeling words on strength scales (not just love or hate)
-- Run AFTER supabase_v23_set_owner.sql (safe to run more than once).
--
-- New tag kind — scale:  '📶 <scale>: <level>'   e.g. '📶 Hate ⇄ Love: -4', '📶 Calm → Angry: +5'
--   two-sided scales run -5 … 0 … +5 (left pole … neutral … right pole); one-sided scales run 0 … +5.
-- Units: Hate ⇄ Love, Sad ⇄ Happy, Calm → Angry, Calm → Afraid, Ways to show love, Caring qualities.
-- Owned by the parent account and public, so the student finds it in the Library.
-- =====================================================================
insert into public.study_sets (id, owner_id, author_name, institution_id, subject_id, level_code, title, description,
                               language, translation_lang, units, visibility)
select '00000000-0000-4000-8000-00000000fee1', p.id, 'Ab', null, 1, 'any', 'Feelings: Word Scales',
  'Feeling words on strength scales: from loathe to adore, from devastated to ecstatic, from calm to furious, and from relaxed to terrified. Plus ways to show love and caring qualities.',
  'en', 'ar', '[{"u": 1, "name": "Hate ⇄ Love"},{"u": 2, "name": "Sad ⇄ Happy"},{"u": 3, "name": "Calm → Angry"},{"u": 4, "name": "Calm → Afraid"},{"u": 5, "name": "Ways to show love"},{"u": 6, "name": "Caring qualities"}]'::jsonb, 'public'
from public.profiles p join auth.users u on u.id = p.id where u.email = 'albarq2000@hotmail.com'
on conflict (id) do update set title = excluded.title, description = excluded.description, units = excluded.units, visibility = excluded.visibility;

